package pt.lawsjustice.visualtest;

import static pt.lawsjustice.visualtest.JusticeVisualQA.*;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Supplier;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.util.RandomSource;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.attachment.AttachmentType;
import pt.lawsjustice.compat.JusticeWallet;
import pt.lawsjustice.data.JusticeData;
import pt.lawsjustice.domain.FinanceLedger;
import pt.lawsjustice.service.CourtService;
import pt.lawsjustice.service.FinanceService;
import pt.lawsjustice.service.PaymentReceipts;

/** Real host wallet, real payment buttons, Crown income receipts and an actual second LAN-world reopen. */
final class JusticeFinanceVisual {
    static final BlockPos INSIDE=new BlockPos(-1,161,4),BOOK=new BlockPos(8,161,-4);
    private static volatile boolean preparedFinance,verified,restarted;private static boolean models,bailUi,bailPaid,fineUi,finePaid,hostPersistence,publicRecords;private static volatile boolean crownIncome;
    private static UUID bailCharge,fineCharge,fineCase,bailPayment,finePayment;private static long originalBalance,originalTreasury,offlineBalance,offlineCrown;private static int serverIdentity;
    private JusticeFinanceVisual(){}
    static void begin(){if(Minecraft.getInstance().screen!=null)Minecraft.getInstance().screen.onClose();Minecraft.getInstance().setScreen(null);server(()->{var p=player();op(p,false);councilPresident(owner);place(INSIDE,"justice_desk");place(BOOK,"register_book");fundFixture();originalBalance=JusticeWallet.balance(p,"CHRONICLES");originalTreasury=treasury();check(originalBalance==10000,"Authored finance fixture wallet was not initialized once");preparedFinance=true;});}
    @SuppressWarnings("unchecked") private static void fundFixture(){try{var p=player();var attachment=(AttachmentType<Object>)((Supplier<?>)Class.forName("pt.cronicasrp.ModAttachments").getField("PROFILE").get(null)).get();Object before=p.getData(attachment);Object funded=before.getClass().getMethod("withBalance",long.class).invoke(before,10000L);p.setData(attachment,funded);}catch(ReflectiveOperationException e){throw new IllegalStateException("Could not initialize the actual Chronicles fixture wallet",e);}}
    private static Object crown(){try{return Class.forName("pt.crownledger.data.TreasuryData").getMethod("get",net.minecraft.server.MinecraftServer.class).invoke(null,player().getServer());}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}
    private static long treasury(){try{Object data=crown(),treasury=data.getClass().getField("treasury").get(data);Class<?> type=Class.forName("pt.crownledger.domain.Treasury$Currency");@SuppressWarnings({"rawtypes","unchecked"})Object currency=Enum.valueOf((Class)type,"CHRONICLES");return (long)treasury.getClass().getMethod("balance",type).invoke(treasury,currency);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}
    private static void openFinance(BlockPos pos){opened=false;server(()->{var p=player();p.connection.teleport(pos.getX()+.5,pos.getY(),pos.getZ()-1.5,0,12);FinanceService.open(p,pos);opened=true;});}
    private static boolean finance(){return ready()&&"finance".equals(string(state(),"kind"));}
    private static JsonObject charge(String kind){if(state()==null||!state().has("charges"))return null;for(var row:state().getAsJsonArray("charges"))if(kind.equals(string(row.getAsJsonObject(),"kind")))return row.getAsJsonObject();return null;}
    private static void compactFinance(){var mc=Minecraft.getInstance();var screen=mc.screen;for(String name:state().get("book").getAsBoolean()?List.of("RECORDS","AUDIT"):state().get("judge").getAsBoolean()?List.of("FINES","BAILS","RECORDS","AUDIT","AUTHORITY"):List.of("FINES","BAILS","RECORDS","AUDIT")){tab(name);screen.resize(mc,320,240);bounds(screen,320,240);for(int n=0;n<24;n++){int x=(int)field(screen,"px"),top=(int)field(screen,"bodyTop"),bottom=(int)field(screen,"bodyBottom");screen.mouseScrolled(x+20,(top+bottom)/2.0,0,-1);bounds(screen,320,240);}scroll(1);}screen.resize(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());}
    private static void validateModel(){var mc=Minecraft.getInstance();var block=BuiltInRegistries.BLOCK.get(key("register_book"));check(block!=Blocks.AIR,"Missing genuine register block");for(var state:block.getStateDefinition().getPossibleStates()){var model=mc.getBlockRenderer().getBlockModel(state);var quads=new ArrayList<net.minecraft.client.renderer.block.model.BakedQuad>();quads.addAll(model.getQuads(state,null,RandomSource.create(0)));for(var dir:Direction.values())quads.addAll(model.getQuads(state,dir,RandomSource.create(0)));check(quads.size()>100,"The original bound register lost its actual geometry");for(var quad:quads)check(!quad.getSprite().contents().name().equals(net.minecraft.client.renderer.texture.MissingTextureAtlasSprite.getLocation()),"Missing genuine register texture");MODEL_QUADS.put(state.toString(),quads.size());}var item=BuiltInRegistries.ITEM.get(key("register_book"));check(item!=Items.AIR&&!mc.getItemRenderer().getModel(new ItemStack(item),null,null,0).getParticleIcon().contents().name().equals(net.minecraft.client.renderer.texture.MissingTextureAtlasSprite.getLocation()),"Missing actual register inventory model");models=true;}
    static void tick(long now)throws Exception {var mc=Minecraft.getInstance();switch(step){
        case 300->{if(!preparedFinance)return;validateModel();openFinance(INSIDE);step++;}
        case 301->{if(!finance())return;check(state().get("judge").getAsBoolean()&&"PRESIDENT".equals(string(state(),"authorityKind")),"A non-operator sworn President cannot authorize bail");compactFinance();tab("AUTHORITY");input("amount","20.00");courtInput("reason","Demonstration bail after six genuine community-service tasks. The original work credits remain unchanged.");check(click("gui.lawsjustice.finance.offer_bail")&&click("gui.lawsjustice.finance.confirm_bail"),"Genuine bail controls failed");request("finance_bail");step++;}
        case 302->{if(!finance()||charge("BAIL")==null)return;bailCharge=UUID.fromString(string(charge("BAIL"),"id"));bailUi=true;tab("AUTHORITY");scroll(1);photo(now);step++;}
        case 303->{capture("laws-justice-bail-authority.png");verified=false;server(()->{check(!player().hasPermissions(2),"Finance President retained operator access");councilPresident(UUID.fromString("e0c13adf-dacc-41de-a6db-d5bca03a390d"));FinanceService.handle(player(),"finance_refresh","{}");verified=true;});step++;}
        case 304->{if(!verified||!finance()||state().get("judge").getAsBoolean())return;compactFinance();tab("BAILS");selected("selectedCharge",bailCharge);scroll(1);photo(now);step++;}
        case 305->{capture("laws-justice-bail-payment.png");check(click("gui.lawsjustice.finance.pay")&&click("gui.lawsjustice.finance.confirm_pay"),"The ordinary prisoner's genuine bail payment controls failed");request("finance_pay");verified=false;step++;}
        case 306->{if(!verified)server(()->{var p=player();var data=JusticeData.get(p.getServer());var c=data.finance().charges().get(bailCharge);if(c==null||!c.status().equals("PAID"))return;check(!data.ledger().active().containsKey(owner),"Paid bail left the actual sentence active");check(JusticeWallet.balance(p,"CHRONICLES")==originalBalance-2000,"Actual bail wallet debit differs from twenty euros");var payment=data.finance().payments().values().stream().filter(v->v.charge().equals(bailCharge)&&v.status().equals("PAID")).findFirst().orElseThrow();check(PaymentReceipts.durable(p.getServer(),payment),"Actual LAN host receipt was not durable in level.dat");bailPayment=payment.id();check(data.work().credits().values().stream().mapToLong(v->v.ticks()).sum()==7200,"Bail altered the awarded work credits");bailPaid=true;verified=true;});if(!verified)return;server(()->{councilPresident(owner);});openCourt();step++;}
        case 307->{if(!courtReady()||!state().get("judge").getAsBoolean())return;tab("CASES");selected("selectedPlayer",owner);courtInput("accusation","Demonstration finance case: the local fixture character damaged a guild notice. This is authored QA, not a real accusation.");check(click("gui.lawsjustice.court.file"),"Genuine finance complaint failed");request("court_file");step++;}
        case 308->{if(!courtReady())return;for(var row:state().getAsJsonArray("cases"))if(string(row.getAsJsonObject(),"accusation").startsWith("Demonstration finance case:"))fineCase=UUID.fromString(string(row.getAsJsonObject(),"id"));if(fineCase==null)return;tab("JUDGMENT");selected("selectedCase",fineCase);check(click("gui.lawsjustice.court.hear"),"Fine skipped a genuine judicial hearing");request("court_hear");step++;}
        case 309->{if(!courtReady())return;JsonObject c=null;for(var row:state().getAsJsonArray("cases"))if(fineCase.toString().equals(string(row.getAsJsonObject(),"id")))c=row.getAsJsonObject();if(c==null||!"HEARING".equals(string(c,"status")))return;tab("JUDGMENT");selected("selectedCase",fineCase);courtInput("verdict_reason","Demonstration judgment: responsibility established; a twenty-five euro fine is imposed without any new prison sentence.");input("fine_amount","25.00");scroll(-1);photo(now);step++;}
        case 310->{capture("laws-justice-fine-judgment.png");check(click("gui.lawsjustice.court.fine")&&click("gui.lawsjustice.court.confirm_fine"),"Genuine fine verdict controls failed");request("court_fine");step++;}
        case 311->{if(!courtReady())return;boolean found=false;for(var row:state().getAsJsonArray("cases"))if(fineCase.toString().equals(string(row.getAsJsonObject(),"id"))&&"FINED".equals(string(row.getAsJsonObject(),"status")))found=true;if(!found)return;fineUi=true;tab("CASES");check(click("gui.lawsjustice.court.finance"),"Physical court-to-payment navigation failed");request("court_finance");step++;}
        case 312->{if(!finance()||charge("FINE")==null)return;fineCharge=UUID.fromString(string(charge("FINE"),"id"));tab("FINES");selected("selectedCharge",fineCharge);scroll(1);photo(now);step++;}
        case 313->{capture("laws-justice-fine-payment.png");check(click("gui.lawsjustice.finance.pay")&&click("gui.lawsjustice.finance.confirm_pay"),"Genuine fine payment failed");request("finance_pay");step++;}
        case 314->{if(!finance()||charge("FINE")==null||!"PAID".equals(string(charge("FINE"),"status")))return;verified=false;server(()->{var p=player();var data=JusticeData.get(p.getServer());check(JusticeWallet.balance(p,"CHRONICLES")==originalBalance-4500,"Actual bail and fine did not debit exactly forty-five euros");check(!data.ledger().active().containsKey(owner),"Paying a fine created another prison sentence");finePayment=data.finance().payments().values().stream().filter(v->v.charge().equals(fineCharge)&&v.status().equals("PAID")).findFirst().orElseThrow().id();finePaid=true;verified=true;});step++;}
        case 315->{if(!finePaid||finePayment==null)return;if(!crownIncome)server(()->{var data=JusticeData.get(player().getServer());if(!data.finance().payments().get(bailPayment).destination().equals("CROWN")||!data.finance().payments().get(finePayment).destination().equals("CROWN"))return;check(treasury()==originalTreasury+4500,"Actual Crown income differs from the backed wallet payments");for(UUID id:List.of(bailPayment,finePayment))pt.lawsjustice.compat.JusticeTreasury.credit(player().getServer(),data.finance().payments().get(id));check(treasury()==originalTreasury+4500,"Replaying actual transfer receipts duplicated Crown income");crownIncome=true;});if(crownIncome){tab("FINES");scroll(1);photo(now);step++;}}
        case 316->{capture("laws-justice-fine-paid.png");tab("RECORDS");scroll(1);photo(now);step++;}
        case 317->{capture("laws-justice-public-decisions.png");tab("AUDIT");scroll(1);photo(now);step++;}
        case 318->{capture("laws-justice-bail-release-history.png");server(()->{var p=player();councilPresident(UUID.fromString("e0c13adf-dacc-41de-a6db-d5bca03a390d"));});openFinance(BOOK);step++;}
        case 319->{if(!finance()||!state().get("book").getAsBoolean())return;check(!state().get("judge").getAsBoolean()&&state().getAsJsonArray("charges").isEmpty()&&state().getAsJsonArray("records").size()>=2,"Public physical register leaked mutation authority or omitted final decisions");compactFinance();tab("RECORDS");scroll(1);photo(now);publicRecords=true;step++;}
        case 320->{capture("laws-justice-register-book-menu.png");mc.screen.onClose();mc.setScreen(null);mc.options.hideGui=true;mc.options.fov().set(41);move(10.8,162.4,-7.1,42,19);step++;}
        case 321->{if(!cameraReady())return;photo(now);step++;}
        case 322->{capture("laws-justice-register-book-model.png");verified=false;server(()->{var p=player();offlineBalance=JusticeWallet.balance(p,"CHRONICLES");offlineCrown=treasury();p.getServer().saveEverything(false,true,true);serverIdentity=System.identityHashCode(p.getServer());verified=true;});step++;}
        case 323->{if(!verified)return;step=324;nextAction=Long.MAX_VALUE;mc.level.disconnect();mc.disconnect(new TitleScreen());offlineAt=System.currentTimeMillis();nextAction=offlineAt+5000;}
        case 324->{check(mc.getSingleplayerServer()==null&&mc.player==null,"The paid LAN world did not actually stop");check(now-offlineAt>=5000,"No actual offline payment persistence interval");step=325;mc.createWorldOpenFlows().openWorld(worldName,()->mc.setScreen(new TitleScreen()));}
        case 325->{if(mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;quiet();if(!restarted)server(()->{var p=player();check(System.identityHashCode(p.getServer())!=serverIdentity&&owner.equals(p.getUUID()),"Actual paid-world restart did not preserve host UUID");var data=JusticeData.get(p.getServer());check(JusticeWallet.balance(p,"CHRONICLES")==offlineBalance&&treasury()==offlineCrown,"LAN reopen restored a stale host wallet or changed Crown income");check(!data.ledger().active().containsKey(owner),"LAN reopen reinstated a paid sentence");for(UUID id:List.of(bailPayment,finePayment)){var payment=data.finance().payments().get(id);check(payment!=null&&payment.status().equals("PAID")&&payment.destination().equals("CROWN")&&PaymentReceipts.durable(p.getServer(),payment),"LAN reopen lost an authoritative payment receipt");pt.lawsjustice.compat.JusticeTreasury.credit(p.getServer(),payment);}check(JusticeWallet.balance(p,"CHRONICLES")==offlineBalance&&treasury()==offlineCrown,"Replayed saved receipts duplicated or lost money after LAN reopen");hostPersistence=true;restarted=true;});if(!restarted)return;publishLan();mc.options.hideGui=false;openFinance(BOOK);step++;}
        case 326->{if(!finance())return;tab("RECORDS");scroll(1);photo(now);step++;}
        case 327->{capture("laws-justice-records-after-lan-restart.png");check(models&&bailUi&&bailPaid&&fineUi&&finePaid&&crownIncome&&hostPersistence&&publicRecords,"Actual financial client coverage incomplete");CHECKS.add("Real non-operator presidential C2S authorized bail and a heard fine. An ordinary prisoner paid bail through genuine controls; the actual Chronicles host wallet lost exactly 45 euros across bail and fine, with authoritative level.dat receipts. Crown received exactly the same money once, including replay after an actual second LAN-world shutdown and reopen. Original work credits remained unchanged.");CHECKS.add("All actual finance authority, payer and public register tabs passed 320x240 bounds and scrolling; the original bound-book model resolves every placed facing. The public physical register contains final verdicts and custody audit, without unresolved accusations or private evidence.");complete(true,"All four development phases passed actual custody, LAN restarts, elected courts, warrants, six Survival work tasks, voluntary fines, authorized bail, persistent host-wallet receipts and idempotent Crown income.");}
        default->throw new IllegalStateException("Unexpected finance visual stage "+step);
    }}
    static void addReport(Map<String,Object> report){report.put("real_finance_models",models);report.put("real_bail_authority_ui",bailUi);report.put("real_bail_payment",bailPaid);report.put("real_fine_verdict_ui",fineUi);report.put("real_fine_payment",finePaid);report.put("real_crown_income_receipts",crownIncome);report.put("real_lan_host_payment_persistence",hostPersistence);report.put("real_public_judicial_records",publicRecords);report.put("finance_initial_wallet_cents",originalBalance);report.put("finance_after_payments_wallet_cents",offlineBalance);report.put("finance_initial_crown_cents",originalTreasury);report.put("finance_after_payments_crown_cents",offlineCrown);report.put("bail_payment_id",bailPayment);report.put("fine_payment_id",finePayment);}
}
